using System.Text.Json;
using HobbyDS9.Application;
using HobbyDS9.Contracts;
using HobbyDS9.Simulation;
using Xunit;
namespace HobbyDS9.Simulation.Tests;
public sealed class ScienceEngineeringIntegrationTests
{
    internal static ScenarioDto Scenario()=>VerticalSliceFixture.Scenario(humans:true,weighted:true);
    internal static CivilizationStateDto Human(ScenarioDto s)=>s.InitialState.Civilizations!.Single(c=>c.CivilizationId=="civ.federation");
    internal static CommandEnvelope Command(ICampaignSession s,CommandKind kind,string id="cmd.research") {var c=s.CaptureSnapshot().Campaign;return new(){CommandId=id,ActorCivilizationId="civ.federation",ExpectedTurn=c.TurnNumber,ExpectedRevision=c.StateRevision,Kind=kind};}
    private static string Json(ICampaignSession s)=>JsonSerializer.Serialize(s.ExportSave());
    private static void Advance(ICampaignSession s){var c=s.CaptureSnapshot().Campaign;Assert.Equal(TurnStatus.Completed,s.AdvanceTurn(c.TurnNumber,c.StateRevision).Status);}
    [Theory][InlineData(0)][InlineData(1)][InlineData(199)][InlineData(420)][InlineData(600)]
    public void SplitConservationAndSimultaneousProgress(int units){var scenario=Scenario();Human(scenario).ScienceAllocationUnits=units;var s=CampaignApplication.StartScenario(scenario);Advance(s);var h=s.ExportSave().GameState.Civilizations!.Single(c=>c.CivilizationId=="civ.federation");var stats=h.Statistics!;Assert.Equal(2400,stats.TotalResearchGenerated);Assert.Equal(4*units,stats.TotalScienceAllocated);Assert.Equal(stats.TotalResearchGenerated,stats.TotalScienceAllocated+stats.TotalEngineeringAllocated);Assert.Equal(stats.TotalScienceAllocated,stats.TotalScienceSpent);Assert.Equal(0,h.ScienceReserve);Assert.Equal(stats.TotalEngineeringAllocated,h.EngineeringReserve);Assert.Equal(stats.TotalScienceSpent,h.Disciplines!.Sum(d=>d.TotalSpent));}
    [Theory][InlineData(-1,CommandErrorCode.InvalidResearchAllocation)][InlineData(601,CommandErrorCode.InvalidResearchAllocation)][InlineData(420,CommandErrorCode.ResearchAllocationUnchanged)]
    public void TopLevelRejectionsAreByteIdenticalAndIdsRetryable(int units,CommandErrorCode error){var s=CampaignApplication.StartScenario(Scenario());var c=Command(s,CommandKind.SetResearchAllocation);c.SetResearchAllocation=new(){ScienceAllocationUnits=units};var before=Json(s);Assert.Equal(error,s.SubmitCommand(c).ErrorCode);Assert.Equal(before,Json(s));c.SetResearchAllocation.ScienceAllocationUnits=300;Assert.True(s.SubmitCommand(c).Accepted);Assert.Equal(1,s.CaptureSnapshot().Campaign.StateRevision);}
    [Theory][InlineData("missing")][InlineData("duplicate")][InlineData("negative")][InlineData("sum599")][InlineData("sum601")][InlineData("null")][InlineData("undefined")][InlineData("null-entry")]
    public void MalformedSixWayCommandRejectsWithoutMutatingAnything(string error)
    {
        var s=CampaignApplication.StartScenario(Scenario());var a=ScienceCoreTests.Equal();switch(error){case "missing":a.RemoveAt(0);break;case "duplicate":a[0].Discipline=a[1].Discipline;break;case "negative":a[0].Weight=-1;a[1].Weight=201;break;case "sum599":a[0].Weight=99;break;case "sum601":a[0].Weight=101;break;case "undefined":a[0].Discipline=0;break;case "null-entry":a[0]=null!;break;}
        var command=Command(s,CommandKind.SetScienceAllocation);command.SetScienceAllocation=new(){Allocations=error=="null"?null:a};var before=Json(s);Assert.Equal(CommandErrorCode.InvalidScienceAllocation,s.SubmitCommand(command).ErrorCode);Assert.Equal(before,Json(s));command.SetScienceAllocation.Allocations=ScienceCoreTests.Equal();command.SetScienceAllocation.Allocations[0].Weight=200;command.SetScienceAllocation.Allocations[1].Weight=0;Assert.True(s.SubmitCommand(command).Accepted);
    }
    [Fact] public void UnchangedReorderedWeightsRejectButAcceptedPayloadIsOwned(){var s=CampaignApplication.StartScenario(Scenario());var c=Command(s,CommandKind.SetScienceAllocation);c.SetScienceAllocation=new(){Allocations=ScienceCoreTests.Equal()};c.SetScienceAllocation.Allocations.Reverse();var before=Json(s);Assert.Equal(CommandErrorCode.ScienceAllocationUnchanged,s.SubmitCommand(c).ErrorCode);Assert.Equal(before,Json(s));c.SetScienceAllocation.Allocations[0].Weight=200;c.SetScienceAllocation.Allocations[1].Weight=0;Assert.True(s.SubmitCommand(c).Accepted);before=Json(s);c.SetScienceAllocation.Allocations.Clear();Assert.Equal(before,Json(s));}
    [Theory][InlineData(0,EngineeringMaturityBand.Development)][InlineData(24,EngineeringMaturityBand.Development)][InlineData(25,EngineeringMaturityBand.Prototype)][InlineData(49,EngineeringMaturityBand.Prototype)][InlineData(50,EngineeringMaturityBand.Operational)][InlineData(99,EngineeringMaturityBand.Operational)][InlineData(100,EngineeringMaturityBand.Mature)]
    public void MaturityBandsStayBounded(int p,EngineeringMaturityBand band){Assert.Equal(p,EngineeringRules.Maturity(p,100));Assert.Equal(band,EngineeringRules.Band(p));}
    [Fact] public void EngineeringProgressRetargetReloadAndOnlyCompletedUnlocksProduction()
    {
        var scenario=Scenario();var h=Human(scenario);foreach(var d in h.Disciplines!)d.Level=2;h.EngineeringReserve=18000;
        var s=CampaignApplication.StartScenario(scenario);var c=Command(s,CommandKind.SetEngineeringTarget);c.SetEngineeringTarget=new(){TargetDefinitionId="engineering.advanced-starship-engineering"};Assert.True(s.SubmitCommand(c).Accepted);Advance(s);
        var actor=new EntityId("civ.federation");var view=ResearchOverviewSnapshot.For(s.CaptureSnapshot(),actor);Assert.Equal(EngineeringMaturityBand.Operational,view.Engineering.Single().Band);Assert.Equal(CommandErrorCode.DesignEngineeringPrerequisiteMissing,StrategicOptions.Production(s.CaptureSnapshot(),actor,new EntityId("colony.sol")).Single(d=>d.Design.DefinitionId.Value=="ship-design.advanced-scout").UnavailableReason);
        c=Command(s,CommandKind.SetEngineeringTarget,"cmd.clear");c.SetEngineeringTarget=new(){TargetDefinitionId=null};Assert.True(s.SubmitCommand(c).Accepted);var save=s.ExportSave();s=CampaignApplication.LoadSave(scenario,JsonSerializer.Deserialize<SaveEnvelopeDto>(JsonSerializer.Serialize(save))!);Assert.Equal(18720,ResearchOverviewSnapshot.For(s.CaptureSnapshot(),actor).Engineering.Single().Progress);
        c=Command(s,CommandKind.SetEngineeringTarget,"cmd.resume");c.SetEngineeringTarget=new(){TargetDefinitionId="engineering.advanced-starship-engineering"};Assert.True(s.SubmitCommand(c).Accepted);for(int i=0;i<30;i++)Advance(s);view=ResearchOverviewSnapshot.For(s.CaptureSnapshot(),actor);Assert.Equal(36000,view.Engineering.Single().Progress);Assert.Equal(100,view.Engineering.Single().MaturityPercent);Assert.Null(view.Target);Assert.True(StrategicOptions.Production(s.CaptureSnapshot(),actor,new EntityId("colony.sol")).Single(d=>d.Design.DefinitionId.Value=="ship-design.advanced-scout").CanEnqueue);
    }
    [Theory][InlineData(EngineeringProjectKind.NewCapability)][InlineData(EngineeringProjectKind.Refinement)][InlineData(EngineeringProjectKind.CivilApplication)]
    public void ProjectKindsApplyNarrowCompletionEffectsAndReload(EngineeringProjectKind kind)
    {
        var scenario=Scenario();var app=scenario.Definitions.EngineeringApplications!.Single();app.ScienceRequirements=new();app.BaseEngineeringCost=1200;app.Kind=kind;app.EffectSummary="Neutral fixture effect";
        if(kind==EngineeringProjectKind.Refinement){scenario.Definitions.DefinitionIds.Add("implementation.fixture-efficiency");app.ParameterChange=new(){ParameterDefinitionId="implementation.fixture-efficiency",Value=9000};foreach(var c in scenario.InitialState.Civilizations!)c.EngineeringParameters!.Add(new(){DefinitionId="implementation.fixture-efficiency",Value=7000});}
        var h=Human(scenario);h.EngineeringReserve=600;var s=CampaignApplication.StartScenario(scenario);var command=Command(s,CommandKind.SetEngineeringTarget);command.SetEngineeringTarget=new(){TargetDefinitionId=app.DefinitionId};Assert.True(s.SubmitCommand(command).Accepted);Advance(s);var save=s.ExportSave();var state=save.GameState.Civilizations!.Single(c=>c.CivilizationId==h.CivilizationId);Assert.Contains(app.DefinitionId,state.MatureEngineeringApplicationDefinitionIds!);Assert.Equal(1200,Assert.Single(state.EngineeringProgress!).Progress);if(kind==EngineeringProjectKind.Refinement)Assert.Equal(9000,Assert.Single(state.EngineeringParameters!).Value);s=CampaignApplication.LoadSave(scenario,save);Assert.Equal(JsonSerializer.Serialize(save),Json(s));
    }
    [Theory][InlineData("kind")][InlineData("missing-effect")][InlineData("unknown-parameter")][InlineData("out-of-range-effect")][InlineData("missing-parameter-state")][InlineData("extra-effect")]
    public void InvalidProjectKindOrEffectRejects(string error)
    {
        var scenario=Scenario();var app=scenario.Definitions.EngineeringApplications!.Single();switch(error){case "kind":app.Kind=0;break;case "missing-effect":app.Kind=EngineeringProjectKind.Refinement;break;case "unknown-parameter":app.Kind=EngineeringProjectKind.Refinement;app.ParameterChange=new(){ParameterDefinitionId="implementation.absent",Value=10};break;case "out-of-range-effect":app.Kind=EngineeringProjectKind.Refinement;app.ParameterChange=new(){ParameterDefinitionId="implementation.fixture",Value=10001};scenario.Definitions.DefinitionIds.Add("implementation.fixture");break;case "missing-parameter-state":app.Kind=EngineeringProjectKind.Refinement;app.ParameterChange=new(){ParameterDefinitionId="implementation.fixture",Value=90};scenario.Definitions.DefinitionIds.Add("implementation.fixture");break;case "extra-effect":app.ParameterChange=new(){ParameterDefinitionId="implementation.fixture",Value=90};break;}
        var before=JsonSerializer.Serialize(scenario);Assert.NotEmpty(CampaignApplication.ValidateScenario(scenario));Assert.Throws<ArgumentException>(()=>CampaignApplication.StartScenario(scenario));Assert.Equal(before,JsonSerializer.Serialize(scenario));
    }
    [Fact] public void MaxedShareBanksAndWarningIsDetached(){var scenario=Scenario();Human(scenario).Disciplines![0].Level=10;var s=CampaignApplication.StartScenario(scenario);Advance(s);var view=ResearchOverviewSnapshot.For(s.CaptureSnapshot(),new EntityId("civ.federation"));Assert.Equal(280,view.ScienceReserve);Assert.True(view.Science[0].AllocatedWhileMaxed);Assert.Equal(0,s.ExportSave().GameState.Civilizations!.Single(c=>c.CivilizationId=="civ.federation").Disciplines![0].TotalSpent);}
    [Fact] public void AiRedistributesOnlyItsMaxedWeightsThroughStampedCommands(){var scenario=VerticalSliceFixture.Scenario(false,weighted:true);scenario.InitialState.Civilizations!.Single(c=>c.CivilizationId=="civ.cardassian").Disciplines![0].Level=10;Human(scenario).Disciplines![0].Level=10;var s=CampaignApplication.StartScenario(scenario);var stamp=s.CaptureSnapshot().Campaign;var result=s.AdvanceTurn(stamp.TurnNumber,stamp.StateRevision);Assert.Contains(result.CommandResults,r=>r.CommandId=="ai-command.t0000000001.a00000000.k7.n00000000"&&r.Accepted);var actors=s.ExportSave().GameState.Civilizations!;Assert.Equal(new[]{0,120,120,120,120,120},actors.Single(c=>c.CivilizationId=="civ.cardassian").ScienceAllocations!.Select(a=>a.Weight));Assert.All(actors.Single(c=>c.CivilizationId=="civ.federation").ScienceAllocations!,a=>Assert.Equal(100,a.Weight));Assert.Equal(stamp.RngState.State,s.CaptureSnapshot().Campaign.RngState.State);}
    [Theory][InlineData(CommandKind.SetResearchAllocation)][InlineData(CommandKind.SetScienceAllocation)][InlineData(CommandKind.SetEngineeringTarget)]
    public void CommandsPreserveStampControlAndDeduplicationGuards(CommandKind kind)
    {
        var scenario=VerticalSliceFixture.Scenario(false,weighted:true);foreach(var d in Human(scenario).Disciplines!)d.Level=2;var s=CampaignApplication.StartScenario(scenario);var c=Command(s,kind);
        if(kind==CommandKind.SetResearchAllocation)c.SetResearchAllocation=new(){ScienceAllocationUnits=300};if(kind==CommandKind.SetScienceAllocation){c.SetScienceAllocation=new(){Allocations=ScienceCoreTests.Equal()};c.SetScienceAllocation.Allocations[0].Weight=200;c.SetScienceAllocation.Allocations[1].Weight=0;}if(kind==CommandKind.SetEngineeringTarget)c.SetEngineeringTarget=new(){TargetDefinitionId="engineering.advanced-starship-engineering"};Assert.True(s.SubmitCommand(c).Accepted);var before=Json(s);Assert.Equal(CommandErrorCode.DuplicateCommand,s.SubmitCommand(c).ErrorCode);c.CommandId="cmd.stale";Assert.Equal(CommandErrorCode.StaleRevision,s.SubmitCommand(c).ErrorCode);c.ExpectedRevision=s.CaptureSnapshot().Campaign.StateRevision;c.ExpectedTurn=0;Assert.Equal(CommandErrorCode.StaleTurn,s.SubmitCommand(c).ErrorCode);c.ExpectedTurn=1;c.ActorCivilizationId="civ.cardassian";Assert.Equal(CommandErrorCode.ActorNotControlled,s.SubmitCommand(c).ErrorCode);Assert.Equal(before,Json(s));
    }
    [Theory][InlineData("seed")][InlineData("allocation")][InlineData("weights")][InlineData("progress")][InlineData("statistics")][InlineData("receipts")][InlineData("parameters")]
    public void OtherPhasesCannotMutateResearchAndRollbackIsComplete(string field)
    {
        var scenario=Scenario();var s=new SimulationSession(VerticalSliceFixture.Session(scenario).ExportSave(),scenario.Definitions,VerticalSliceFixture.Compatibility(scenario),new Dictionary<CommandKind,ICommandHandler>(),(phase,state)=>{if(phase!=StrategicTurnPhase.Economy)return true;var h=state.Civilizations!.Single(c=>c.CivilizationId=="civ.federation");if(field=="seed")h.ResearchDiscoverySeed=42;if(field=="allocation")h.ScienceAllocationUnits=300;if(field=="weights"){h.ScienceAllocations![0].Weight=200;h.ScienceAllocations[1].Weight=0;}if(field=="progress")h.Disciplines![0].ProgressTowardNextLevel=1;if(field=="statistics")h.Statistics!.TotalBreakthroughs=1;if(field=="receipts")state.LastResearchReceipts!.Add(new(){CivilizationId="civ.federation",Category="allocation",Amount=1});if(field=="parameters")h.EngineeringParameters!.Add(new(){DefinitionId="implementation.foreign",Value=1});return true;});var before=JsonSerializer.Serialize(s.ExportSave());var c=s.CaptureSnapshot();Assert.Throws<InvalidOperationException>(()=>s.AdvanceTurn(c.TurnNumber,c.StateRevision));Assert.Equal(before,JsonSerializer.Serialize(s.ExportSave()));
    }
    [Theory][InlineData("science-reserve")][InlineData("engineering-reserve")][InlineData("generated")]
    public void OverflowRollsBackAllEarlierEconomy(string field){var scenario=Scenario();var h=Human(scenario);if(field=="science-reserve")h.ScienceReserve=long.MaxValue;if(field=="engineering-reserve")h.EngineeringReserve=long.MaxValue;if(field=="generated"){h.Statistics!.TotalResearchGenerated=long.MaxValue;h.Statistics.TotalScienceAllocated=long.MaxValue;}var s=CampaignApplication.StartScenario(scenario);var before=Json(s);var c=s.CaptureSnapshot().Campaign;Assert.Throws<OverflowException>(()=>s.AdvanceTurn(c.TurnNumber,c.StateRevision));Assert.Equal(before,Json(s));}
    [Fact] public void OldSaveAndContentLeaveLiveSessionUntouched(){var scenario=Scenario();var s=CampaignApplication.StartScenario(scenario);var before=Json(s);var save=s.ExportSave();save.SaveFormatVersion=12;Assert.Throws<ArgumentException>(()=>CampaignApplication.LoadSave(scenario,save));scenario.Definitions.ContentFormatVersion=8;Assert.Throws<ArgumentException>(()=>CampaignApplication.StartScenario(scenario));Assert.Equal(before,Json(s));}
}
